        },
        "people": {
            "description": "Primary contact for information about the dataset.",
            "type": "array",
            "additionalItems": false,
            "required": [
                "first_name",
                "last_name",
                "email"
            ],
            "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "first_name": {
                        "type": [
                            "string",
                            "null"
                        ]
                    },
                    "last_name": {
                        "type": "string"
                    },
                    "roles": {
                        "type": "array",
                        "items": {
                            "enum": [
                                "pointOfContact"
                            ]
                        },
                        "default": [
                            "pointOfContact"
                        ]
                    },
                    "email": {
                        "type": [
                            "string",
                            "null"
                        ]
                    }
                }
            }
        },
        "organisations": {
            "description": "Organisations connected to the dataset",
            "type": "array",
            "additionalItems": false,
            "maxItems": 1,
            "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "name": {
                        "type": "string"
                    },
                    "roles": {
                        "type": "array",
                        "items": {
                            "type": "string",
