        },
        "description": {
            "type": "string",
            "description": "The engine description"
        },
        "url": {
            "type": "string",
            "description": "The engine url or homepage",
            "format": "uri"
        },
        "version": {
            "type": "string",
            "description": "The engine version"
        },
        "languages": {
            "type": "array",
            "description": "The list of supported languages",
            "items": {
                "type": "string",
                "enum": [
                    "coffeescript",
                    "css",
                    "html",
                    "xml",
                    "javascript",
                    "json",
                    "jsx",
                    "sass",
                    "typescript",
                    "c",
                    "cpp",
                    "csharp",
                    "groovy",
                    "php",
                    "ruby",
                    "fortran",
                    "plsql",
                    "scala",
                    "objectivec",
                    "perl",
                    "swift",
                    "python",
                    "java",
                    "pug"
                ]
            }
        },
        "extensions": {
            "type": "array",
            "description": "Common file extensions parsed by engine",
            "items": {
                "type": "string"
            }
        },
        "configs": {
            "type": "array",
            "description": "List of file names which could be treated as engine config",
            "items": {
                "type": "string"
            }
        },
        "license": {
            "type": "string",
            "description": "The engine license",
            "enum": [
                "Unknown",
