                    "type": "string"
                }
            },
            "title": "Holding",
            "type": "object"
        },
        "issue": {
            "additionalProperties": false,
            "form": {
                "hideExpression": "field.parent.model.type !== 'issue'"
            },
            "properties": {
                "display_text": {
                    "minLength": 1,
                    "title": "displayed text",
                    "type": "string"
                },
                "expected_date": {
                    "_format": "date",
                    "form": {
                        "hideExpression": "field.parent.model.regular",
                        "type": "datepicker",
                        "validation": {
                            "messages": {
                                "pattern": "Should be in the ISO 8601, YYYY-MM-DD."
                            }
                        },
                        "wrappers": [
                            "form-field"
                        ]
                    },
                    "pattern": "\\d{4}-((0[1-9])|(1[0-2]))-(((0[1-9])|[1-2][0-9])|(3[0-1]))$",
                    "title": "Expected date",
                    "type": "string",
                    "validationMessage": "Should be in the following format: 2022-12-31 (YYYY-MM-DD)."
                },
                "received_date": {
                    "_format": "date",
                    "form": {
                        "type": "datepicker",
                        "validation": {
                            "messages": {
                                "pattern": "Should be in the ISO 8601, YYYY-MM-DD."
                            }
                        },
                        "wrappers": [
                            "form-field"
                        ]
                    },
                    "pattern": "\\d{4}-((0[1-9])|(1[0-2]))-(((0[1-9])|[1-2][0-9])|(3[0-1]))$",
                    "title": "Date of reception",
                    "type": "string",
                    "validationMessage": "Should be in the following format: 2022-12-31 (YYYY-MM-DD)."
                },
                "regular": {
                    "default": true,
                    "form": {
                        "hideExpression": "true"
                    },
                    "title": "Regularity",
                    "type": "boolean"
                },
                "status": {
                    "default": "received",
                    "enum": [
                        "received",
                        "claimed",
                        "deleted"
                    ],
                    "title": "Issue status",
                    "type": "string"
                }
            },
            "propertiesOrder": [
                "display_text",
                "received_date",
                "expected_date",
                "regular",
                "status"
            ],
            "required": [
                "display_text",
                "received_date",
                "expected_date",
                "regular",
                "status"
            ],
            "title": "Issue",
            "type": "object"
        },
        "item_type": {
            "form": {
                "hideExpression": "field.parent.model.type === 'issue'"
            },
            "properties": {
                "$ref": {
                    "form": {
                        "remoteOptions": {
                            "type": "item_types"
                        }
                    },
                    "pattern": "^https://ils.rero.ch/api/item_types/.+?$",
                    "title": "Item Type URI",
                    "type": "string"
                }
            },
            "required": [
                "$ref"
